package com.reg21meme.dross.boss.ratking.trophy.client;

import com.reg21meme.dross.Dross;
import net.minecraft.resources.ResourceLocation;
import software.bernie.geckolib.core.animatable.GeoAnimatable;
import software.bernie.geckolib.model.GeoModel;

/**
 * The Rat King trophy's files, all generated by {@code tools/ratking} ({@code ratkit/trophies.py}): his model plus the
 * trophy's dirt mound (its own copies, {@code geo/block/rat_king_trophy.geo.json} for the placed trophy and
 * {@code geo/item/rat_king_trophy.geo.json} for the item: GeckoLib shares a model's bones between everything drawn with
 * it, so the boss, the placed trophies and the items each get their own), the five held poses
 * ({@code animations/block/rat_king_trophy}) and the trophy's own 256 x 256 textures (his texels with the mound's under
 * them): the look, the glowing parts (his orb and crown gem) and his red rage eyes.
 */
public class RatKingTrophyGeoModel<T extends GeoAnimatable> extends GeoModel<T>
{
    public static final ResourceLocation BLOCK_MODEL = new ResourceLocation(Dross.MODID, "geo/block/rat_king_trophy.geo.json");
    public static final ResourceLocation ITEM_MODEL = new ResourceLocation(Dross.MODID, "geo/item/rat_king_trophy.geo.json");
    public static final ResourceLocation ANIMATIONS = new ResourceLocation(Dross.MODID, "animations/block/rat_king_trophy.animation.json");
    /** The trophy's textures: its look, the glowing parts and his red eyes. */
    public static final ResourceLocation TEXTURE = texture("");
    public static final ResourceLocation GLOW = texture("_glow");
    public static final ResourceLocation RAGE = texture("_rage");

    private static ResourceLocation texture(String suffix)
    {
        return new ResourceLocation(Dross.MODID, "textures/block/rat_king_trophy/rat_king_trophy" + suffix + ".png");
    }

    private final ResourceLocation model;

    /** @param model {@link #BLOCK_MODEL} or {@link #ITEM_MODEL} */
    public RatKingTrophyGeoModel(ResourceLocation model)
    {
        this.model = model;
    }

    @Override
    public ResourceLocation getModelResource(T animatable)
    {
        return this.model;
    }

    @Override
    public ResourceLocation getTextureResource(T animatable)
    {
        return TEXTURE;
    }

    @Override
    public ResourceLocation getAnimationResource(T animatable)
    {
        return ANIMATIONS;
    }
}
